// @vitest-environment node
// Cross-implementation tests: the browser crypto must produce exactly what
// the Go code produces (shared/e2ee, shared/chunker). The fixtures are
// generated by the Go tests (`go test ./shared/e2ee ./shared/chunker -update`).
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { fromHex, toHex } from '../bytes';
import {
  CHUNK_OVERHEAD,
  CorruptError,
  Keys,
  WrongKeyError,
  createKeys,
  isEncryptedName,
  isEncryptedPath,
  unlockWithPassphrase,
  unlockWithRecoveryKey,
  withNewRecoveryKey,
  withPassphrase,
  type KDFParams,
} from '../keys';
import { chunks, cut, DEFAULT_PARAMS, type Params } from '../fastcdc';
import { formatRecoveryKey, parseRecoveryKey } from '../recovery';
import type { KeyBundle } from '../../api/types';

const root = (p: string) => fileURLToPath(new URL('../../../../../' + p, import.meta.url));
const vectors = JSON.parse(readFileSync(root('shared/e2ee/testdata/vectors.json'), 'utf8')) as {
  master: string;
  fingerprint: string;
  auth_key: string;
  names: { Plain: string; Enc: string }[];
  paths: { Plain: string; Enc: string }[];
  chunks: { Plain: string; Sealed: string }[];
  file_hashes: { SHA256: string; Mapped: string }[];
  bundle: KeyBundle;
  passphrase: string;
  recovery_key: string;
};
const cdc = JSON.parse(readFileSync(root('shared/chunker/testdata/cdc-vectors.json'), 'utf8')) as {
  seed: number;
  length: number;
  params: { Min: number; Avg: number; Max: number };
  sizes: number[];
}[];

const cheap: KDFParams = { alg: 'argon2id', time: 1, memory_kib: 8 * 1024, threads: 1 };

describe('e2ee vectors shared with Go', () => {
  it('derives the same subkeys', async () => {
    const k = await Keys.fromMaster(fromHex(vectors.master));
    expect(k.fingerprint).toBe(vectors.fingerprint);
    expect(k.authKey).toBe(vectors.auth_key);
  });

  it('encrypts names and paths byte-for-byte like Go', async () => {
    const k = await Keys.fromMaster(fromHex(vectors.master));
    for (const n of vectors.names) {
      expect(k.encryptName(n.Plain)).toBe(n.Enc);
      expect(k.decryptName(n.Enc)).toBe(n.Plain);
      expect(isEncryptedName(n.Enc)).toBe(true);
    }
    for (const p of vectors.paths) {
      expect(k.encryptPath(p.Plain)).toBe(p.Enc);
      expect(k.decryptPath(p.Enc)).toBe(p.Plain);
      expect(isEncryptedPath(p.Enc)).toBe(true);
    }
  });

  it('seals chunks and maps file hashes like Go', async () => {
    const k = await Keys.fromMaster(fromHex(vectors.master));
    for (const c of vectors.chunks) {
      expect(toHex(k.sealChunk(fromHex(c.Plain)))).toBe(c.Sealed);
      expect(toHex(k.openChunk(fromHex(c.Sealed)))).toBe(c.Plain);
      expect(fromHex(c.Sealed).length).toBe(fromHex(c.Plain).length + CHUNK_OVERHEAD);
    }
    for (const f of vectors.file_hashes) expect(k.fileHash(fromHex(f.SHA256))).toBe(f.Mapped);
  });

  it('unlocks a Go-made bundle with the passphrase and the recovery key', async () => {
    const a = await unlockWithPassphrase(vectors.bundle, vectors.passphrase);
    expect(toHex(a.masterKey())).toBe(vectors.master);
    const b = await unlockWithRecoveryKey(vectors.bundle, vectors.recovery_key.toLowerCase().replace(/-/g, ' '));
    expect(toHex(b.masterKey())).toBe(vectors.master);
  });
});

describe('e2ee behaviour', () => {
  it('rejects a wrong passphrase or recovery key', async () => {
    await expect(unlockWithPassphrase(vectors.bundle, vectors.passphrase + 'x')).rejects.toBeInstanceOf(WrongKeyError);
    await expect(unlockWithRecoveryKey(vectors.bundle, 'AAAA-AAAA-AAAA-AAAA-AAAA-AAAA-AAAA-AAAA')).rejects.toBeInstanceOf(WrongKeyError);
    await expect(unlockWithRecoveryKey(vectors.bundle, 'not a key')).rejects.toBeInstanceOf(WrongKeyError);
  });

  it('detects tampering with any byte of a chunk or name', async () => {
    const k = await Keys.fromMaster(fromHex(vectors.master));
    const sealed = k.sealChunk(new TextEncoder().encode('tamper test'));
    for (let i = 0; i < sealed.length; i++) {
      const mod = sealed.slice();
      mod[i]! ^= 0x01;
      expect(() => k.openChunk(mod)).toThrow(CorruptError);
    }
    expect(() => k.openChunk(sealed.subarray(0, sealed.length - 1))).toThrow(CorruptError);
    const name = k.encryptName('secret.txt');
    const flipped = name.slice(0, 10) + (name[10] === 'A' ? 'B' : 'A') + name.slice(11);
    expect(() => k.decryptName(flipped)).toThrow();
  });

  it('creates keys whose bundle the same code opens, and re-wraps them', async () => {
    const { bundle, keys, recoveryKey } = await createKeys('browser passphrase!', cheap);
    expect((await unlockWithPassphrase(bundle, 'browser passphrase!')).fingerprint).toBe(keys.fingerprint);
    expect((await unlockWithRecoveryKey(bundle, recoveryKey)).fingerprint).toBe(keys.fingerprint);
    const b2 = await withPassphrase(bundle, keys, 'a different passphrase', cheap);
    await expect(unlockWithPassphrase(b2, 'browser passphrase!')).rejects.toBeInstanceOf(WrongKeyError);
    expect((await unlockWithPassphrase(b2, 'a different passphrase')).fingerprint).toBe(keys.fingerprint);
    expect((await unlockWithRecoveryKey(b2, recoveryKey)).fingerprint).toBe(keys.fingerprint);
    const r = await withNewRecoveryKey(b2, keys);
    await expect(unlockWithRecoveryKey(r.bundle, recoveryKey)).rejects.toBeInstanceOf(WrongKeyError);
    expect((await unlockWithRecoveryKey(r.bundle, r.recoveryKey)).fingerprint).toBe(keys.fingerprint);
    await expect(createKeys('short', cheap)).rejects.toThrow(/at least 10/);
  });

  it('formats recovery keys like Go', () => {
    const raw = new Uint8Array(20).fill(0x5a);
    expect(formatRecoveryKey(raw)).toBe(vectors.recovery_key);
    expect(parseRecoveryKey(vectors.recovery_key)).toEqual(raw);
    expect(parseRecoveryKey('too short')).toBeNull();
  });

  it('recognises encrypted name shapes like the server does', () => {
    expect(isEncryptedName('report.pdf')).toBe(false);
    expect(isEncryptedName('~$Budget.xlsx')).toBe(false);
    expect(isEncryptedName('~' + 'A'.repeat(54))).toBe(false);
    expect(isEncryptedPath(vectors.paths[0]!.Enc + '/plain')).toBe(false);
  });
});

function splitmix(seed: number, n: number): Uint8Array {
  const M = (1n << 64n) - 1n;
  const out = new Uint8Array(n);
  let x = BigInt(seed);
  for (let i = 0; i < n; i += 8) {
    x = (x + 0x9e3779b97f4a7c15n) & M;
    let z = x;
    z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & M;
    z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & M;
    z ^= z >> 31n;
    for (let j = 0; j < 8 && i + j < n; j++) out[i + j] = Number((z >> BigInt(8 * j)) & 0xffn);
  }
  return out;
}

describe('FastCDC port', () => {
  it('cuts at the same offsets as the Go chunker', async () => {
    for (const c of cdc) {
      const data = splitmix(c.seed, c.length);
      const p: Params = { min: c.params.Min, avg: c.params.Avg, max: c.params.Max };
      const sizes: number[] = [];
      // Small, uneven reads must not change the result.
      const read = async (s: number, e: number) => data.slice(s, e);
      for await (const ch of chunks(read, data.length, p)) sizes.push(ch.data.length);
      expect(sizes).toEqual(c.sizes);
    }
  }, 60_000);

  it('handles tiny inputs', () => {
    expect(cut(new Uint8Array(10))).toBe(10);
    expect(cut(new Uint8Array(0))).toBe(0);
    expect(cut(new Uint8Array(DEFAULT_PARAMS.max + 5)) <= DEFAULT_PARAMS.max).toBe(true);
  });
});
